const EXPORT_CONFIG = {
  theme: "Sustainability - Clean Energy Transition Hub",
  duration: 25,
  fps: 60,
  width: 3840,
  height: 2160,
  aspectRatio: "16:9",
  videoBitrate: 100000000,
  videoBitrateMbps: 100
};

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const u = minSide * 0.001;
  const cx = width * 0.5;
  const cy = height * 0.5;
  const TWO_PI = Math.PI * 2;

  const clamp = (val, min, max) => Math.max(min, Math.min(max, val));
  const easeInOutCubic = (x) => x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  const easeOutCubic = (x) => 1 - Math.pow(1 - x, 3);

  const getSceneEnvelope = (p) => {
    const enter = easeOutCubic(clamp(p / 0.12, 0, 1));
    const exit = 1 - easeInOutCubic(clamp((p - 0.88) / 0.12, 0, 1));
    return enter * exit;
  };

  const roundedRectPath = (ctx, x, y, w, h, r) => {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  };

  const polygonPath = (ctx, x, y, r, sides, rotation = -Math.PI * 0.5) => {
    ctx.beginPath();
    for (let i = 0; i < sides; i++) {
      const a = rotation + (i * TWO_PI) / sides;
      const px = x + Math.cos(a) * r;
      const py = y + Math.sin(a) * r;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  };

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.shadowBlur = 0;
  ctx.shadowColor = "transparent";

  // 1. STATIC MODERN AESTHETIC GRADIENT BACKGROUND (Non-moving)
  const bgLinear = ctx.createLinearGradient(0, 0, width, height);
  bgLinear.addColorStop(0, "#071B1E");
  bgLinear.addColorStop(0.5, "#0B292C");
  bgLinear.addColorStop(1, "#051417");
  ctx.fillStyle = bgLinear;
  ctx.fillRect(0, 0, width, height);

  const bgRadial = ctx.createRadialGradient(cx, cy, 40 * u, cx, cy, 780 * u);
  bgRadial.addColorStop(0, "rgba(22, 82, 76, 0.42)");
  bgRadial.addColorStop(0.6, "rgba(13, 48, 49, 0.18)");
  bgRadial.addColorStop(1, "rgba(5, 20, 23, 0)");
  ctx.fillStyle = bgRadial;
  ctx.fillRect(0, 0, width, height);

  // Static Architectural Backdrop Framing (Completely stationary)
  ctx.strokeStyle = "rgba(167, 243, 208, 0.06)";
  ctx.lineWidth = 1.5 * u;
  ctx.beginPath();
  ctx.arc(cx, cy, 445 * u, 0, TWO_PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, 465 * u, 0, TWO_PI);
  ctx.stroke();

  // 2. SHARED OUTER PRECISION ICON FRAME (Continuous & Seamless across 25s)
  const globalCycles = loopT / duration;
  const outerRot = globalCycles * TWO_PI;

  // Base Emblem Plate
  const plateGrad = ctx.createLinearGradient(cx - 280 * u, cy - 280 * u, cx + 280 * u, cy + 280 * u);
  plateGrad.addColorStop(0, "#0F3538");
  plateGrad.addColorStop(1, "#082024");
  ctx.fillStyle = plateGrad;
  ctx.beginPath();
  ctx.arc(cx, cy, 340 * u, 0, TWO_PI);
  ctx.fill();

  ctx.strokeStyle = "#2DD4BF";
  ctx.lineWidth = 3 * u;
  ctx.beginPath();
  ctx.arc(cx, cy, 340 * u, 0, TWO_PI);
  ctx.stroke();

  // Inner Structural Ring
  ctx.strokeStyle = "rgba(153, 246, 228, 0.25)";
  ctx.lineWidth = 2 * u;
  ctx.beginPath();
  ctx.arc(cx, cy, 316 * u, 0, TWO_PI);
  ctx.stroke();

  // Outer Segmented Precision Bezel (Zone: 365u to 415u - strictly isolated)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(outerRot);
  for (let i = 0; i < 12; i++) {
    const a0 = (i * TWO_PI) / 12 + 0.04;
    const a1 = ((i + 0.65) * TWO_PI) / 12 - 0.04;
    ctx.strokeStyle = i % 2 === 0 ? "#34D399" : "#2DD4BF";
    ctx.lineWidth = 2.5 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 380 * u, a0, a1);
    ctx.stroke();

    const midA = (a0 + a1) * 0.5;
    const nx = Math.cos(midA) * 404 * u;
    const ny = Math.sin(midA) * 404 * u;
    ctx.fillStyle = "#A7F3D0";
    ctx.beginPath();
    ctx.arc(nx, ny, 3.5 * u, 0, TWO_PI);
    ctx.fill();
  }
  ctx.restore();

  // Counter-Rotating Cardinal Track (Zone: 356u)
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(-outerRot);
  for (let i = 0; i < 4; i++) {
    const a = (i * TWO_PI) / 4;
    ctx.strokeStyle = "rgba(240, 253, 244, 0.45)";
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.arc(0, 0, 356 * u, a - 0.22, a + 0.22);
    ctx.stroke();
  }
  ctx.restore();

  // 3. SCENE CONTENT (Strictly clipped & spaced inside 305u radius)
  const env = getSceneEnvelope(sceneProgress);
  const scaleTransform = 0.92 + 0.08 * env;

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, 308 * u, 0, TWO_PI);
  ctx.clip();

  ctx.translate(cx, cy);
  ctx.scale(scaleTransform, scaleTransform);
  ctx.globalAlpha = env;

  if (currentScene === 0) {
    // =========================================================================
    // SCENE 1: SOLAR PHOTOVOLTAIC & STORAGE HUB (Strictly non-overlapping bands)
    // =========================================================================
    const sunY = -92 * u;
    const sunR = 46 * u;
    const solarPhase = sceneProgress * TWO_PI * 2;

    // 1A. Precision Sun Core (Radius 0 to 46u around sunY)
    const sunGrad = ctx.createLinearGradient(0, sunY - sunR, 0, sunY + sunR);
    sunGrad.addColorStop(0, "#FDE68A");
    sunGrad.addColorStop(1, "#F59E0B");
    ctx.fillStyle = sunGrad;
    ctx.beginPath();
    ctx.arc(0, sunY, sunR, 0, TWO_PI);
    ctx.fill();

    ctx.strokeStyle = "#FEF3C7";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Inner Sun Detail Ring (Radius 30u)
    ctx.strokeStyle = "#78350F";
    ctx.lineWidth = 2 * u;
    ctx.beginPath();
    ctx.arc(0, sunY, 30 * u, 0, TWO_PI);
    ctx.stroke();

    // 1B. Concentric Solar Ring (Radius 64u - clear 18u gap from sun core)
    ctx.save();
    ctx.translate(0, sunY);
    ctx.rotate(solarPhase * 0.5);
    for (let i = 0; i < 8; i++) {
      const a = (i * TWO_PI) / 8;
      ctx.strokeStyle = "#FBBF24";
      ctx.lineWidth = 2.5 * u;
      ctx.beginPath();
      ctx.arc(0, 0, 64 * u, a + 0.08, a + (TWO_PI / 8) - 0.08);
      ctx.stroke();
    }
    ctx.restore();

    // 1C. Radial Ray Ticks (Radius 80u to 96u - clear 16u gap from ring)
    ctx.save();
    ctx.translate(0, sunY);
    ctx.rotate(-solarPhase * 0.25);
    for (let i = 0; i < 16; i++) {
      const a = (i * TWO_PI) / 16;
      const rIn = 80 * u;
      const rOut = (i % 2 === 0 ? 96 : 90) * u;
      ctx.strokeStyle = i % 2 === 0 ? "#FDE68A" : "#34D399";
      ctx.lineWidth = 2.5 * u;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * rIn, Math.sin(a) * rIn);
      ctx.lineTo(Math.cos(a) * rOut, Math.sin(a) * rOut);
      ctx.stroke();
    }
    ctx.restore();

    // 1D. Energy Transfer Guide Channels (Y: +12u to +48u - clear gap below rays at +4u)
    const channelX = [-120 * u, -60 * u, 0, 60 * u, 120 * u];
    for (let i = 0; i < channelX.length; i++) {
      const x = channelX[i];
      ctx.strokeStyle = "rgba(167, 243, 208, 0.28)";
      ctx.lineWidth = 2 * u;
      ctx.beginPath();
      ctx.moveTo(x, 14 * u);
      ctx.lineTo(x, 48 * u);
      ctx.stroke();

      // Synchronized non-overlapping energy bead along channel
      const beadProgress = ((sceneProgress * 3 + i * 0.2) % 1);
      const beadY = (18 + beadProgress * 26) * u;
      ctx.fillStyle = "#FDE68A";
      ctx.beginPath();
      ctx.arc(x, beadY, 3.5 * u, 0, TWO_PI);
      ctx.fill();
    }

    // 1E. Geometric Solar Panel Array (Y: +56u to +148u - separated from channels)
    const panelTopY = 56 * u;
    const panelBotY = 146 * u;
    const panelTopW = 150 * u;
    const panelBotW = 216 * u;

    const panelGrad = ctx.createLinearGradient(0, panelTopY, 0, panelBotY);
    panelGrad.addColorStop(0, "#10B981");
    panelGrad.addColorStop(1, "#047857");

    ctx.fillStyle = panelGrad;
    ctx.beginPath();
    ctx.moveTo(-panelTopW, panelTopY);
    ctx.lineTo(panelTopW, panelTopY);
    ctx.lineTo(panelBotW, panelBotY);
    ctx.lineTo(-panelBotW, panelBotY);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#A7F3D0";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Internal Solar Grid Lines (Strictly inside trapezoid boundaries)
    ctx.strokeStyle = "#064E3B";
    ctx.lineWidth = 2 * u;
    for (let r = 1; r <= 2; r++) {
      const rf = r / 3;
      const py = panelTopY + (panelBotY - panelTopY) * rf;
      const pw = panelTopW + (panelBotW - panelTopW) * rf;
      ctx.beginPath();
      ctx.moveTo(-pw + 4 * u, py);
      ctx.lineTo(pw - 4 * u, py);
      ctx.stroke();
    }

    for (let c = -2; c <= 2; c++) {
      const cf = c / 3;
      ctx.beginPath();
      ctx.moveTo(panelTopW * cf, panelTopY + 3 * u);
      ctx.lineTo(panelBotW * cf, panelBotY - 3 * u);
      ctx.stroke();
    }

    // 1F. Precision Battery Storage Unit (Y: +168u to +222u - 22u gap below panel)
    // Short Dual Conduit Connectors (Y: +146u to +168u)
    ctx.strokeStyle = "#34D399";
    ctx.lineWidth = 3 * u;
    ctx.beginPath();
    ctx.moveTo(-45 * u, panelBotY);
    ctx.lineTo(-45 * u, 168 * u);
    ctx.moveTo(45 * u, panelBotY);
    ctx.lineTo(45 * u, 168 * u);
    ctx.stroke();

    const batX = -115 * u;
    const batY = 168 * u;
    const batW = 230 * u;
    const batH = 52 * u;

    ctx.fillStyle = "#062C30";
    roundedRectPath(ctx, batX, batY, batW, batH, 10 * u);
    ctx.fill();
    ctx.strokeStyle = "#6EE7B7";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Battery Terminal Cap (Right side, isolated)
    ctx.fillStyle = "#34D399";
    roundedRectPath(ctx, batX + batW + 6 * u, batY + 14 * u, 8 * u, 24 * u, 3 * u);
    ctx.fill();

    // 5 Precision Charge Cells Inside Battery (Spaced with 8u padding)
    const cellCount = 5;
    const cellGap = 7 * u;
    const cellPad = 10 * u;
    const totalCellW = batW - cellPad * 2 - cellGap * (cellCount - 1);
    const cellW = totalCellW / cellCount;
    const cellH = batH - cellPad * 2;

    const chargeCycle = (0.35 + 0.65 * (0.5 - 0.5 * Math.cos(sceneProgress * TWO_PI))) * cellCount;

    for (let i = 0; i < cellCount; i++) {
      const cxPos = batX + cellPad + i * (cellW + cellGap);
      const cyPos = batY + cellPad;
      const fillLevel = clamp(chargeCycle - i, 0, 1);

      ctx.strokeStyle = "rgba(167, 243, 208, 0.3)";
      ctx.lineWidth = 1.5 * u;
      roundedRectPath(ctx, cxPos, cyPos, cellW, cellH, 4 * u);
      ctx.stroke();

      if (fillLevel > 0.02) {
        const cellGrad = ctx.createLinearGradient(cxPos, cyPos, cxPos, cyPos + cellH);
        cellGrad.addColorStop(0, "#6EE7B7");
        cellGrad.addColorStop(1, "#10B981");
        ctx.fillStyle = cellGrad;
        roundedRectPath(ctx, cxPos + 2 * u, cyPos + 2 * u, (cellW - 4 * u) * fillLevel, cellH - 4 * u, 2.5 * u);
        ctx.fill();
      }
    }

  } else if (currentScene === 1) {
    // =========================================================================
    // SCENE 2: TWIN WIND TURBINES, CONTOUR HILLS & POWER METER
    // =========================================================================
    const windPhase = sceneProgress * TWO_PI * 2;

    // 2A. Upper Circular Power Meter Arc (Zone: R = 250u, angles -145 deg to -35 deg)
    const meterR = 248 * u;
    const startAngle = -Math.PI * 0.78;
    const endAngle = -Math.PI * 0.22;

    // Meter Track
    ctx.strokeStyle = "rgba(167, 243, 208, 0.2)";
    ctx.lineWidth = 10 * u;
    ctx.beginPath();
    ctx.arc(0, 0, meterR, startAngle, endAngle);
    ctx.stroke();

    // Active Meter Fill (Smooth harmonic oscillation between 65% and 95%)
    const meterProgress = 0.68 + 0.24 * Math.sin(sceneProgress * TWO_PI);
    const activeEnd = startAngle + (endAngle - startAngle) * meterProgress;
    const meterGrad = ctx.createLinearGradient(-180 * u, -240 * u, 180 * u, -240 * u);
    meterGrad.addColorStop(0, "#2DD4BF");
    meterGrad.addColorStop(1, "#FBBF24");

    ctx.strokeStyle = meterGrad;
    ctx.lineWidth = 10 * u;
    ctx.beginPath();
    ctx.arc(0, 0, meterR, startAngle, activeEnd);
    ctx.stroke();

    // Precision Scale Ticks Outside Meter (R = 264u to 274u)
    for (let i = 0; i <= 12; i++) {
      const a = startAngle + ((endAngle - startAngle) * i) / 12;
      ctx.strokeStyle = i / 12 <= meterProgress ? "#A7F3D0" : "rgba(167, 243, 208, 0.25)";
      ctx.lineWidth = 2 * u;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * 264 * u, Math.sin(a) * 264 * u);
      ctx.lineTo(Math.cos(a) * 274 * u, Math.sin(a) * 274 * u);
      ctx.stroke();
    }

    // 2B. Dynamic Bezier Wind Streamlines (Isolated horizontal corridors)
    const windLanes = [
      { y: -158 * u, xStart: -225 * u, xEnd: 225 * u, amp: 8 * u, offset: 0.0 },
      { y: -130 * u, xStart: -245 * u, xEnd: 245 * u, amp: 10 * u, offset: 0.35 },
      { y: 20 * u,   xStart: -250 * u, xEnd: 250 * u, amp: 9 * u, offset: 0.7 }
    ];

    for (let i = 0; i < windLanes.length; i++) {
      const lane = windLanes[i];
      ctx.strokeStyle = "rgba(153, 246, 228, 0.22)";
      ctx.lineWidth = 2 * u;
      ctx.beginPath();
      ctx.moveTo(lane.xStart, lane.y);
      ctx.bezierCurveTo(
        -80 * u, lane.y - lane.amp,
        80 * u, lane.y + lane.amp,
        lane.xEnd, lane.y
      );
      ctx.stroke();

      // Moving streamlined wind segment along the curve
      const segProgress = (sceneProgress * 2 + lane.offset) % 1;
      const segCenter = lane.xStart + (lane.xEnd - lane.xStart) * segProgress;
      const segHalf = 32 * u;
      const sx0 = clamp(segCenter - segHalf, lane.xStart, lane.xEnd);
      const sx1 = clamp(segCenter + segHalf, lane.xStart, lane.xEnd);

      if (sx1 - sx0 > 8 * u) {
        const y0 = lane.y + Math.sin((sx0 / (250 * u)) * Math.PI) * (lane.amp * 0.45);
        const y1 = lane.y + Math.sin((sx1 / (250 * u)) * Math.PI) * (lane.amp * 0.45);
        ctx.strokeStyle = "#5EEAD4";
        ctx.lineWidth = 3 * u;
        ctx.beginPath();
        ctx.moveTo(sx0, y0);
        ctx.lineTo(sx1, y1);
        ctx.stroke();
      }
    }

    // 2C. Twin Wind Turbines (Left: X = -105u, Right: X = +105u -> 210u separation, Blade R = 74u)
    // Max blade reach between turbines: -105 + 74 = -31u and +105 - 74 = +31u (62u clear gap!)
    const turbines = [
      { x: -105 * u, hubY: -48 * u, baseY: 118 * u, bladeR: 74 * u, phaseOffset: 0 },
      { x: 105 * u,  hubY: -28 * u, baseY: 126 * u, bladeR: 68 * u, phaseOffset: Math.PI / 3 }
    ];

    for (let idx = 0; idx < turbines.length; idx++) {
      const tb = turbines[idx];

      // Tapered Tower Mast (Stopped cleanly before hub circle)
      const mastTopY = tb.hubY + 14 * u;
      const mastGrad = ctx.createLinearGradient(tb.x - 10 * u, mastTopY, tb.x + 10 * u, tb.baseY);
      mastGrad.addColorStop(0, "#CCFBF1");
      mastGrad.addColorStop(1, "#2DD4BF");

      ctx.fillStyle = mastGrad;
      ctx.beginPath();
      ctx.moveTo(tb.x - 4.5 * u, mastTopY);
      ctx.lineTo(tb.x + 4.5 * u, mastTopY);
      ctx.lineTo(tb.x + 10 * u, tb.baseY);
      ctx.lineTo(tb.x - 10 * u, tb.baseY);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = "#F0FDFA";
      ctx.lineWidth = 2 * u;
      ctx.stroke();

      // Rotating 3-Blade Assembly
      ctx.save();
      ctx.translate(tb.x, tb.hubY);
      ctx.rotate(windPhase + tb.phaseOffset);

      for (let b = 0; b < 3; b++) {
        ctx.save();
        ctx.rotate((b * TWO_PI) / 3);

        const bladeGrad = ctx.createLinearGradient(0, -14 * u, 0, -tb.bladeR);
        bladeGrad.addColorStop(0, "#A7F3D0");
        bladeGrad.addColorStop(1, "#10B981");

        ctx.fillStyle = bladeGrad;
        ctx.beginPath();
        ctx.moveTo(-3 * u, -13 * u);
        ctx.lineTo(-7.5 * u, -tb.bladeR * 0.45);
        ctx.lineTo(-1.5 * u, -tb.bladeR);
        ctx.lineTo(2.5 * u, -tb.bladeR);
        ctx.lineTo(5.5 * u, -tb.bladeR * 0.45);
        ctx.lineTo(3 * u, -13 * u);
        ctx.closePath();
        ctx.fill();

        ctx.strokeStyle = "#ECFDF5";
        ctx.lineWidth = 2 * u;
        ctx.stroke();

        ctx.restore();
      }

      // Center Hub Nacelle (Radius 13u)
      ctx.fillStyle = "#0F3538";
      ctx.beginPath();
      ctx.arc(0, 0, 13 * u, 0, TWO_PI);
      ctx.fill();
      ctx.strokeStyle = "#FDE68A";
      ctx.lineWidth = 3 * u;
      ctx.stroke();

      ctx.fillStyle = "#FBBF24";
      ctx.beginPath();
      ctx.arc(0, 0, 4.5 * u, 0, TWO_PI);
      ctx.fill();

      ctx.restore();
    }

    // 2D. Layered Geometric Contour Hills (Bottom Zone: Y = +105u to +310u)
    // Back Hill Layer
    const hill1Grad = ctx.createLinearGradient(0, 100 * u, 0, 260 * u);
    hill1Grad.addColorStop(0, "#10B981");
    hill1Grad.addColorStop(1, "#065F46");
    ctx.fillStyle = hill1Grad;
    ctx.beginPath();
    ctx.moveTo(-320 * u, 132 * u);
    ctx.quadraticCurveTo(-110 * u, 88 * u, 40 * u, 128 * u);
    ctx.quadraticCurveTo(180 * u, 162 * u, 320 * u, 118 * u);
    ctx.lineTo(320 * u, 320 * u);
    ctx.lineTo(-320 * u, 320 * u);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#A7F3D0";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Front Hill Layer (Non-intersecting top ridge below Hill 1)
    const hill2Grad = ctx.createLinearGradient(0, 145 * u, 0, 310 * u);
    hill2Grad.addColorStop(0, "#059669");
    hill2Grad.addColorStop(1, "#064E3B");
    ctx.fillStyle = hill2Grad;
    ctx.beginPath();
    ctx.moveTo(-320 * u, 182 * u);
    ctx.quadraticCurveTo(-60 * u, 154 * u, 110 * u, 172 * u);
    ctx.quadraticCurveTo(220 * u, 184 * u, 320 * u, 158 * u);
    ctx.lineTo(320 * u, 320 * u);
    ctx.lineTo(-320 * u, 320 * u);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#6EE7B7";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Parallel Topographic Contour Lines on Front Hill (Spaced 24u apart)
    for (let c = 1; c <= 2; c++) {
      const offsetY = c * 26 * u;
      ctx.strokeStyle = "rgba(167, 243, 208, 0.35)";
      ctx.lineWidth = 2 * u;
      ctx.beginPath();
      ctx.moveTo(-300 * u, 182 * u + offsetY);
      ctx.quadraticCurveTo(-60 * u, 154 * u + offsetY, 110 * u, 172 * u + offsetY);
      ctx.quadraticCurveTo(220 * u, 184 * u + offsetY, 300 * u, 158 * u + offsetY);
      ctx.stroke();
    }

  } else {
    // =========================================================================
    // SCENE 3: SMART GRID HEXAGONAL SHIELD, ENERGY LEAF & DISTRIBUTION NODES
    // =========================================================================
    const gridPhase = sceneProgress * TWO_PI;
    const hexOuterR = 132 * u;
    const hexInnerR = 108 * u;
    const nodeRingR = 236 * u;

    // 3A. 6 Radial Smart-Grid Distribution Channels & Outer Nodes
    // Strictly spanning between R = 142u (outside hex) and R = 208u (inside node ring)
    for (let i = 0; i < 6; i++) {
      const angle = -Math.PI * 0.5 + (i * TWO_PI) / 6;
      const cosA = Math.cos(angle);
      const sinA = Math.sin(angle);

      const lineStartR = 142 * u;
      const lineEndR = 206 * u;

      // Static Conduit Track
      ctx.strokeStyle = "rgba(94, 234, 212, 0.35)";
      ctx.lineWidth = 2.5 * u;
      ctx.beginPath();
      ctx.moveTo(cosA * lineStartR, sinA * lineStartR);
      ctx.lineTo(cosA * lineEndR, sinA * lineEndR);
      ctx.stroke();

      // Synchronized Outward Energy Pulse Packet along Conduit
      const packetP = (sceneProgress * 2 + (i % 2) * 0.5) % 1;
      const packetR = lineStartR + (lineEndR - lineStartR) * packetP;
      ctx.fillStyle = "#FDE68A";
      ctx.beginPath();
      ctx.arc(cosA * packetR, sinA * packetR, 4 * u, 0, TWO_PI);
      ctx.fill();

      // Outer Distribution Node Hub (Centered at R = 236u, Radius = 24u)
      const nx = cosA * nodeRingR;
      const ny = sinA * nodeRingR;

      const nodeGrad = ctx.createLinearGradient(nx - 20 * u, ny - 20 * u, nx + 20 * u, ny + 20 * u);
      nodeGrad.addColorStop(0, "#115E59");
      nodeGrad.addColorStop(1, "#064E3B");

      ctx.fillStyle = nodeGrad;
      polygonPath(ctx, nx, ny, 24 * u, 6, angle);
      ctx.fill();

      ctx.strokeStyle = "#5EEAD4";
      ctx.lineWidth = 2.5 * u;
      ctx.stroke();

      // Inner Node Status Indicator (Harmonious sequential modulation without glow)
      const nodeActive = 0.5 + 0.5 * Math.sin(gridPhase * 2 - i * (TWO_PI / 6));
      ctx.fillStyle = nodeActive > 0.5 ? "#FBBF24" : "#34D399";
      ctx.beginPath();
      ctx.arc(nx, ny, (5.5 + 2.5 * nodeActive) * u, 0, TWO_PI);
      ctx.fill();
    }

    // 3B. Hexagonal Perimeter Link Segments Connecting the 6 Outer Nodes
    for (let i = 0; i < 6; i++) {
      const a1 = -Math.PI * 0.5 + (i * TWO_PI) / 6;
      const a2 = -Math.PI * 0.5 + ((i + 1) * TWO_PI) / 6;

      const x1 = Math.cos(a1) * nodeRingR;
      const y1 = Math.sin(a1) * nodeRingR;
      const x2 = Math.cos(a2) * nodeRingR;
      const y2 = Math.sin(a2) * nodeRingR;

      // Trim ends by 30u so lines never touch or overlap node hexagons
      const dx = x2 - x1;
      const dy = y2 - y1;
      const len = Math.hypot(dx, dy);
      const trim = (30 * u) / len;

      const sx = x1 + dx * trim;
      const sy = y1 + dy * trim;
      const ex = x1 + dx * (1 - trim);
      const ey = y1 + dy * (1 - trim);

      ctx.strokeStyle = "rgba(167, 243, 208, 0.28)";
      ctx.lineWidth = 2 * u;
      ctx.beginPath();
      ctx.moveTo(sx, sy);
      ctx.lineTo(ex, ey);
      ctx.stroke();

      // Midpoint Micro-Relay Dot
      const mx = (sx + ex) * 0.5;
      const my = (sy + ey) * 0.5;
      ctx.fillStyle = "#6EE7B7";
      ctx.beginPath();
      ctx.arc(mx, my, 3 * u, 0, TWO_PI);
      ctx.fill();
    }

    // 3C. Central Hexagonal Smart-Grid Shield (Outer R = 132u, Inner R = 108u)
    const shieldGrad = ctx.createLinearGradient(-100 * u, -120 * u, 100 * u, 120 * u);
    shieldGrad.addColorStop(0, "#0D9488");
    shieldGrad.addColorStop(0.5, "#059669");
    shieldGrad.addColorStop(1, "#064E3B");

    ctx.fillStyle = shieldGrad;
    polygonPath(ctx, 0, 0, hexOuterR, 6);
    ctx.fill();

    ctx.strokeStyle = "#A7F3D0";
    ctx.lineWidth = 3.5 * u;
    ctx.stroke();

    // Inner Recessed Hexagon Plate (R = 106u)
    const innerShieldGrad = ctx.createLinearGradient(0, -106 * u, 0, 106 * u);
    innerShieldGrad.addColorStop(0, "#06373A");
    innerShieldGrad.addColorStop(1, "#042226");

    ctx.fillStyle = innerShieldGrad;
    polygonPath(ctx, 0, 0, hexInnerR, 6);
    ctx.fill();

    ctx.strokeStyle = "#2DD4BF";
    ctx.lineWidth = 2 * u;
    ctx.stroke();

    // Precision Corner Rivets inside Outer Shield Border (R = 120u)
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI * 0.5 + (i * TWO_PI) / 6;
      ctx.fillStyle = "#CCFBF1";
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 120 * u, Math.sin(a) * 120 * u, 2.5 * u, 0, TWO_PI);
      ctx.fill();
    }

    // 3D. Central Eco-Leaf & Clean Energy Bolt Emblem (Strictly within R <= 78u)
    const emblemScale = 0.96 + 0.04 * Math.sin(gridPhase);
    ctx.save();
    ctx.scale(emblemScale, emblemScale);

    // Symmetrical Vector Leaf Silhouette (Height: -68u to +68u, Width: -48u to +48u)
    const leafGrad = ctx.createLinearGradient(-45 * u, -68 * u, 45 * u, 68 * u);
    leafGrad.addColorStop(0, "#34D399");
    leafGrad.addColorStop(1, "#059669");

    ctx.fillStyle = leafGrad;
    ctx.beginPath();
    ctx.moveTo(0, -68 * u);
    ctx.bezierCurveTo(54 * u, -34 * u, 54 * u, 36 * u, 0, 68 * u);
    ctx.bezierCurveTo(-54 * u, 36 * u, -54 * u, -34 * u, 0, -68 * u);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#ECFDF5";
    ctx.lineWidth = 3 * u;
    ctx.stroke();

    // Geometric Lightning Bolt Inside Leaf (Strictly bounded inside leaf contour: -38u to +38u)
    const boltGrad = ctx.createLinearGradient(0, -40 * u, 0, 40 * u);
    boltGrad.addColorStop(0, "#FEF3C7");
    boltGrad.addColorStop(1, "#F59E0B");

    ctx.fillStyle = boltGrad;
    ctx.beginPath();
    ctx.moveTo(6 * u, -38 * u);
    ctx.lineTo(-18 * u, 4 * u);
    ctx.lineTo(2 * u, 4 * u);
    ctx.lineTo(-6 * u, 38 * u);
    ctx.lineTo(18 * u, -4 * u);
    ctx.lineTo(-2 * u, -4 * u);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = "#78350F";
    ctx.lineWidth = 1.8 * u;
    ctx.stroke();

    ctx.restore();
  }

  ctx.restore();

  // 4. SCENE PROGRESS INDICATOR DOTS (Bottom Bezel Area: Y = cy + 432u, Isolated & Clean)
  for (let s = 0; s < sceneCount; s++) {
    const dotX = cx + (s - 1) * 28 * u;
    const dotY = cy + 434 * u;
    const isActive = s === currentScene;

    ctx.fillStyle = isActive ? "#34D399" : "rgba(167, 243, 208, 0.25)";
    ctx.beginPath();
    ctx.arc(dotX, dotY, (isActive ? 5 : 3.5) * u, 0, TWO_PI);
    ctx.fill();

    if (isActive) {
      ctx.strokeStyle = "#A7F3D0";
      ctx.lineWidth = 1.5 * u;
      ctx.beginPath();
      ctx.arc(dotX, dotY, 9 * u, 0, TWO_PI);
      ctx.stroke();
    }
  }

  ctx.restore();
}

/* =====================================================================
   KONSEP 1 — LEAF CIRCUIT ENERGY
   Tema: Sustainability | Durasi: 25 detik | 3 Scene | 16:9 | FHD / 2K / 4K
   Gaya: Single Icon Motion — Modern Flat Vector, Outline Style, Soft Gradient
   Canvas API murni — tanpa glow, tanpa asset eksternal, background statis
   ===================================================================== */

function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
function seg(p, a, b) { return clamp01((p - a) / (b - a)); }
function lerp(a, b, k) { return a + (b - a) * k; }
function easeInOutCubic(x) { return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
function easeOutCubic(x) { return 1 - Math.pow(1 - x, 3); }
function smoothstep(x) { x = clamp01(x); return x * x * (3 - 2 * x); }
function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
function mixRGB(c1, c2, k) {
  return 'rgb(' + Math.round(lerp(c1[0], c2[0], k)) + ',' +
    Math.round(lerp(c1[1], c2[1], k)) + ',' +
    Math.round(lerp(c1[2], c2[2], k)) + ')';
}

/* Fase build-in (scene 1) -> hold (scene 2) -> build-out (scene 3) */
function phase(cs, p, a0, a1, b0, b1) {
  if (cs === 0) return easeInOutCubic(seg(p, a0, a1));
  if (cs === 1) return 1;
  return 1 - easeInOutCubic(seg(p, b0, b1));
}

/* ---------- Geometri path presisi (polyline dengan panjang kumulatif) ---------- */
function cubicPts(p0, p1, p2, p3, n) {
  const out = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n, m = 1 - s;
    const a = m * m * m, b = 3 * m * m * s, c = 3 * m * s * s, d = s * s * s;
    out.push([a * p0[0] + b * p1[0] + c * p2[0] + d * p3[0],
              a * p0[1] + b * p1[1] + c * p2[1] + d * p3[1]]);
  }
  return out;
}
function quadPts(p0, p1, p2, n) {
  const out = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n, m = 1 - s;
    out.push([m * m * p0[0] + 2 * m * s * p1[0] + s * s * p2[0],
              m * m * p0[1] + 2 * m * s * p1[1] + s * s * p2[1]]);
  }
  return out;
}
function makePath(pts) {
  const cum = [0];
  for (let i = 1; i < pts.length; i++) {
    cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  return { pts: pts, cum: cum, len: cum[cum.length - 1] };
}
function findSeg(path, d) {
  const c = path.cum, n = c.length;
  if (d <= 0) return 0;
  if (d >= path.len) return n - 2;
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (c[mid] <= d) lo = mid; else hi = mid;
  }
  return lo;
}
function pointAt(path, d) {
  const i = findSeg(path, d);
  const a = path.pts[i], b = path.pts[i + 1] || a;
  const sl = path.cum[i + 1] - path.cum[i];
  const k = sl > 0 ? clamp01((d - path.cum[i]) / sl) : 0;
  return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
}
function strokeRange(ctx, path, a, b) {
  if (a < 0) a = 0;
  if (b > path.len) b = path.len;
  if (b - a < 1e-5) return;
  const p0 = pointAt(path, a);
  ctx.beginPath();
  ctx.moveTo(p0[0], p0[1]);
  let i = findSeg(path, a) + 1;
  while (i < path.pts.length && path.cum[i] < b) {
    ctx.lineTo(path.pts[i][0], path.pts[i][1]);
    i++;
  }
  const p1 = pointAt(path, b);
  ctx.lineTo(p1[0], p1[1]);
  ctx.stroke();
}

/* ---------- Data daun (unit lokal, skala S) ---------- */
const LEAF = (function () {
  const right = cubicPts([0, 0.85], [0.95, 0.55], [0.80, -0.55], [0, -1.0], 90);
  const left = right.map(function (q) { return [-q[0], q[1]]; });
  const shape = right.concat(left.slice().reverse().slice(1));
  const stem = makePath(quadPts([0.07, 1.22], [0.015, 1.02], [0, 0.85], 30));
  const midrib = makePath([[0, 0.85], [0, -0.74]]);
  const defs = [
    [[0, 0.55], [0.36, 0.19], [0.36, -0.12]],
    [[0, 0.15], [0.20, -0.05], [0.20, -0.36]],
    [[0, -0.32], [0.24, -0.56]]
  ];
  const veins = [];
  for (let i = 0; i < defs.length; i++) {
    for (let sd = 0; sd < 2; sd++) {
      const side = sd === 0 ? 1 : -1;
      const pts = defs[i].map(function (q) { return [q[0] * side, q[1]]; });
      veins.push({
        i: i,
        side: side,
        path: makePath(pts),
        pulse: makePath([[0, 0.85]].concat(pts)),
        node: pts[pts.length - 1],
        junction: pts[0],
        jFrac: (0.85 - pts[0][1]) / 1.59
      });
    }
  }
  return {
    right: makePath(right),
    left: makePath(left),
    shape: shape,
    stem: stem,
    midrib: midrib,
    veins: veins
  };
})();

const HEXES = [
  [-0.66, -0.22, 0.030, 0.0, 1],
  [-0.79, 0.08, 0.021, 1.3, -1],
  [-0.61, 0.27, 0.025, 2.1, 1],
  [0.65, -0.27, 0.023, 0.7, -1],
  [0.78, -0.02, 0.030, 2.6, 1],
  [0.62, 0.25, 0.021, 4.0, -1]
];

const LAYER_A = { trace: [17, 121, 94], node: [255, 255, 255], pulse: '#F2A93B', lit: [242, 169, 59] };
const LAYER_B = { trace: [240, 255, 247], node: [17, 121, 94], pulse: '#FFD166', lit: [255, 209, 102] };

function leafShapePath(ctx) {
  const s = LEAF.shape;
  ctx.beginPath();
  ctx.moveTo(s[0][0], s[0][1]);
  for (let i = 1; i < s.length; i++) ctx.lineTo(s[i][0], s[i][1]);
  ctx.closePath();
}

function hexPath(ctx, x, y, r, rot) {
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = rot + i * Math.PI / 3;
    const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

function drawCircuit(ctx, st, L) {
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* jalur sirkuit */
  ctx.strokeStyle = rgba(L.trace, 1);
  ctx.lineWidth = 0.03;
  strokeRange(ctx, LEAF.midrib, 0, st.midrib * LEAF.midrib.len);
  for (let k = 0; k < LEAF.veins.length; k++) {
    const v = LEAF.veins[k];
    strokeRange(ctx, v.path, 0, st.vein[v.i] * v.path.len);
  }

  /* titik junction pada tulang daun */
  ctx.fillStyle = rgba(L.trace, 1);
  for (let k = 0; k < LEAF.veins.length; k += 2) {
    const v = LEAF.veins[k];
    const js = smoothstep(seg(st.midrib, v.jFrac - 0.01, v.jFrac + 0.05));
    if (js <= 0) continue;
    ctx.beginPath();
    ctx.arc(0, v.junction[1], 0.03 * js, 0, Math.PI * 2);
    ctx.fill();
  }

  /* pulsa energi */
  ctx.strokeStyle = L.pulse;
  ctx.lineWidth = 0.04;
  for (let k = 0; k < st.segs.length; k++) {
    const s = st.segs[k];
    strokeRange(ctx, s.path, s.a, s.b);
  }

  /* node ujung */
  ctx.lineWidth = 0.02;
  ctx.strokeStyle = rgba(L.trace, 1);
  for (let k = 0; k < LEAF.veins.length; k++) {
    const v = LEAF.veins[k];
    const ns = easeOutCubic(seg(st.vein[v.i], 0.86, 1));
    if (ns <= 0) continue;
    const lit = st.veinLit[k];
    ctx.beginPath();
    ctx.arc(v.node[0], v.node[1], 0.045 * ns * (1 + 0.22 * lit), 0, Math.PI * 2);
    ctx.fillStyle = mixRGB(L.node, L.lit, lit);
    ctx.fill();
    ctx.stroke();
  }
  const ms = easeOutCubic(seg(st.midrib, 0.9, 1));
  if (ms > 0) {
    ctx.beginPath();
    ctx.arc(0, -0.74, 0.05 * ms * (1 + 0.22 * st.midLit), 0, Math.PI * 2);
    ctx.fillStyle = mixRGB(L.node, L.lit, st.midLit);
    ctx.fill();
    ctx.stroke();
  }
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  /* pengaman presisi floating-point di batas scene */
  const cs = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const p = Math.abs(sceneProgress - (loopT / sceneDuration - cs)) < 0.5 ? clamp01(sceneProgress) : clamp01(loopT / sceneDuration - cs);

  const W = width, H = height;
  const U = Math.min(W, H);
  const minSide = U;
  const S = minSide * 0.30;
  const cx = W * 0.5, cy = H * 0.5;
  const TAU = Math.PI * 2;
  const cycle = loopT / duration;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);

  /* ---------- BACKGROUND (statis) ---------- */
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, '#EEF8F2');
  bg.addColorStop(0.5, '#DDF2EA');
  bg.addColorStop(1, '#CFE6F0');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  let rg = ctx.createRadialGradient(W * 0.08, H * 0.1, 0, W * 0.08, H * 0.1, minSide * 0.85);
  rg.addColorStop(0, 'rgba(176,232,204,0.50)');
  rg.addColorStop(1, 'rgba(176,232,204,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);

  rg = ctx.createRadialGradient(W * 0.94, H * 0.92, 0, W * 0.94, H * 0.92, minSide * 0.85);
  rg.addColorStop(0, 'rgba(158,208,236,0.50)');
  rg.addColorStop(1, 'rgba(158,208,236,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);

  /* ---------- STATE ANIMASI ---------- */
  const st = {
    stem: phase(cs, p, 0.00, 0.14, 0.955, 1.00),
    outline: phase(cs, p, 0.08, 0.50, 0.84, 0.97),
    interior: phase(cs, p, 0.38, 0.60, 0.74, 0.84),
    midrib: phase(cs, p, 0.42, 0.66, 0.84, 0.95),
    vein: [
      phase(cs, p, 0.56, 0.76, 0.78, 0.90),
      phase(cs, p, 0.66, 0.86, 0.74, 0.86),
      phase(cs, p, 0.76, 0.96, 0.70, 0.82)
    ],
    segs: [],
    veinLit: [],
    midLit: 0
  };

  let fillLevel = 0;
  if (cs === 2) {
    fillLevel = easeInOutCubic(seg(p, 0.04, 0.42)) * (1 - easeInOutCubic(seg(p, 0.62, 0.76)));
  }

  /* pulsa energi: kecepatan konstan, bercabang dari tangkai ke tiap node */
  const waves = cs === 1 ? [0.04, 0.36, 0.68] : (cs === 2 ? [0.40] : []);
  const PL = 0.16, SPEED = 9;
  function evalPulse(path) {
    let lit = 0;
    const span = path.len + 3 * PL;
    for (let w = 0; w < waves.length; w++) {
      const head = (p - waves[w]) * SPEED;
      if (head <= 0 || head >= span) continue;
      const a = Math.max(0, head - PL), b = Math.min(head, path.len);
      if (b > a) st.segs.push({ path: path, a: a, b: b });
      const dd = Math.abs(head - (path.len + PL));
      lit = Math.max(lit, smoothstep(1 - dd / (1.5 * PL)));
    }
    return lit;
  }
  st.midLit = evalPulse(LEAF.midrib);
  for (let k = 0; k < LEAF.veins.length; k++) st.veinLit.push(evalPulse(LEAF.veins[k].pulse));

  /* ---------- PARTIKEL HEKSAGON (di luar area ikon) ---------- */
  for (let i = 0; i < HEXES.length; i++) {
    const h = HEXES[i];
    const hx = cx + (h[0] + Math.cos(TAU * cycle + h[3]) * 0.005) * minSide;
    const hy = cy + (h[1] + Math.sin(TAU * cycle + h[3]) * 0.010) * minSide;
    const hr = h[2] * minSide;
    const rot = h[3] + h[4] * (Math.PI / 3) * cycle;
    const hg = ctx.createLinearGradient(hx, hy - hr, hx, hy + hr);
    hg.addColorStop(0, 'rgba(255,255,255,0.75)');
    hg.addColorStop(1, 'rgba(186,234,212,0.60)');
    hexPath(ctx, hx, hy, hr, rot);
    ctx.fillStyle = hg;
    ctx.fill();
    ctx.lineJoin = 'round';
    ctx.lineWidth = minSide * 0.0032;
    ctx.strokeStyle = 'rgba(15,94,75,0.55)';
    ctx.stroke();
    hexPath(ctx, hx, hy, hr * 0.48, rot);
    ctx.lineWidth = minSide * 0.0024;
    ctx.strokeStyle = 'rgba(15,94,75,0.35)';
    ctx.stroke();
  }

  /* ---------- IKON UTAMA ---------- */
  const floatY = Math.sin(TAU * 2 * cycle) * 0.008 * minSide;
  ctx.translate(cx, cy + floatY);
  ctx.scale(S, S);

  /* frame cincin outline */
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.arc(0, 0, 1.42, 0, TAU);
  ctx.lineWidth = 0.012;
  ctx.strokeStyle = 'rgba(15,94,75,0.16)';
  ctx.stroke();

  const ringRot = (TAU / 3) * cycle;
  ctx.lineWidth = 0.028;
  ctx.strokeStyle = 'rgba(15,94,75,0.42)';
  for (let i = 0; i < 3; i++) {
    const a = ringRot + i * TAU / 3 - Math.PI / 2;
    ctx.beginPath();
    ctx.arc(0, 0, 1.42, a - 0.25, a + 0.25);
    ctx.stroke();
  }

  /* cincin ekspansi (scene 3) */
  if (cs === 2) {
    const rings = [[0.42, 0.64], [0.50, 0.72]];
    for (let i = 0; i < rings.length; i++) {
      const q = seg(p, rings[i][0], rings[i][1]);
      if (q <= 0 || q >= 1) continue;
      ctx.beginPath();
      ctx.arc(0, 0, lerp(1.42, 1.72, easeOutCubic(q)), 0, TAU);
      ctx.lineWidth = 0.012;
      ctx.strokeStyle = 'rgba(15,94,75,' + (0.45 * (1 - q)).toFixed(4) + ')';
      ctx.stroke();
    }
  }

  ctx.rotate(-0.2);
  ctx.translate(0, -0.1);

  /* isi dalam daun (tint lembut) */
  if (st.interior > 0.001) {
    leafShapePath(ctx);
    ctx.fillStyle = 'rgba(255,255,255,' + (0.6 * st.interior).toFixed(4) + ')';
    ctx.fill();
  }

  /* sirkuit layer A */
  drawCircuit(ctx, st, LAYER_A);

  /* isi gradient naik dari pangkal (scene 3) */
  if (fillLevel > 0.001) {
    const yTop = lerp(0.87, -1.02, fillLevel);
    ctx.save();
    leafShapePath(ctx);
    ctx.clip();
    ctx.beginPath();
    ctx.rect(-1.5, yTop, 3, 3);
    ctx.clip();
    const fg = ctx.createLinearGradient(0, 0.85, 0, -1);
    fg.addColorStop(0, '#1E9E78');
    fg.addColorStop(0.55, '#2FB487');
    fg.addColorStop(1, '#4CC596');
    ctx.fillStyle = fg;
    ctx.fillRect(-1.5, -1.5, 3, 3);
    drawCircuit(ctx, st, LAYER_B);
    ctx.restore();
  }

  /* outline daun + tangkai */
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  ctx.lineWidth = 0.055;
  ctx.strokeStyle = '#0F5E4B';
  strokeRange(ctx, LEAF.stem, 0, st.stem * LEAF.stem.len);
  strokeRange(ctx, LEAF.right, 0, st.outline * LEAF.right.len);
  strokeRange(ctx, LEAF.left, 0, st.outline * LEAF.left.len);

  ctx.restore();
}

/* =====================================================================
   KONSEP 2 — SOLAR PANEL SUNRISE
   Tema: Sustainability | Durasi: 25 detik | 3 Scene | 16:9 | FHD / 2K / 4K
   Gaya: Single Icon Motion — Modern Flat Vector, Outline Style, Soft Gradient
   Canvas API murni — tanpa glow, tanpa asset eksternal, background statis
   ===================================================================== */

function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
function seg(p, a, b) { return clamp01((p - a) / (b - a)); }
function lerp(a, b, k) { return a + (b - a) * k; }
function easeInOutCubic(x) { return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2; }
function easeOutCubic(x) { return 1 - Math.pow(1 - x, 3); }
function easeInOutSine(x) { return -(Math.cos(Math.PI * x) - 1) / 2; }
function smoothstep(x) { x = clamp01(x); return x * x * (3 - 2 * x); }

/* Fase build-in (scene 1) -> hold (scene 2) -> build-out (scene 3) */
function phase(cs, p, a0, a1, b0, b1) {
  if (cs === 0) return easeInOutCubic(seg(p, a0, a1));
  if (cs === 1) return 1;
  return 1 - easeInOutCubic(seg(p, b0, b1));
}

/* ---------- Path presisi ---------- */
function cubicPts(p0, p1, p2, p3, n) {
  const out = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n, m = 1 - s;
    const a = m * m * m, b = 3 * m * m * s, c = 3 * m * s * s, d = s * s * s;
    out.push([a * p0[0] + b * p1[0] + c * p2[0] + d * p3[0],
              a * p0[1] + b * p1[1] + c * p2[1] + d * p3[1]]);
  }
  return out;
}
function makePath(pts) {
  const cum = [0];
  for (let i = 1; i < pts.length; i++) {
    cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  }
  return { pts: pts, cum: cum, len: cum[cum.length - 1] };
}
function findSeg(path, d) {
  const c = path.cum, n = c.length;
  if (d <= 0) return 0;
  if (d >= path.len) return n - 2;
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (c[mid] <= d) lo = mid; else hi = mid;
  }
  return lo;
}
function pointAt(path, d) {
  const i = findSeg(path, d);
  const a = path.pts[i], b = path.pts[i + 1] || a;
  const sl = path.cum[i + 1] - path.cum[i];
  const k = sl > 0 ? clamp01((d - path.cum[i]) / sl) : 0;
  return [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k];
}
function strokeRange(ctx, path, a, b) {
  if (a < 0) a = 0;
  if (b > path.len) b = path.len;
  if (b - a < 1e-5) return;
  const p0 = pointAt(path, a);
  ctx.beginPath();
  ctx.moveTo(p0[0], p0[1]);
  let i = findSeg(path, a) + 1;
  while (i < path.pts.length && path.cum[i] < b) {
    ctx.lineTo(path.pts[i][0], path.pts[i][1]);
    i++;
  }
  const p1 = pointAt(path, b);
  ctx.lineTo(p1[0], p1[1]);
  ctx.stroke();
}
/* setengah rounded-rect: dari tengah bawah ke tengah atas (side: 1 kanan, -1 kiri) */
function roundRectHalf(x0, y0, x1, y1, r, side, n) {
  const cxm = (x0 + x1) / 2, hw = (x1 - x0) / 2;
  const ex = cxm + side * hw, ix = cxm + side * (hw - r);
  const pts = [[cxm, y1], [ix, y1]];
  const a0 = Math.PI / 2, a1 = side > 0 ? 0 : Math.PI;
  for (let i = 1; i <= n; i++) {
    const a = lerp(a0, a1, i / n);
    pts.push([ix + Math.cos(a) * r, y1 - r + Math.sin(a) * r]);
  }
  pts.push([ex, y0 + r]);
  const b0 = side > 0 ? 0 : Math.PI, b1 = side > 0 ? -Math.PI / 2 : Math.PI * 1.5;
  for (let i = 1; i <= n; i++) {
    const a = lerp(b0, b1, i / n);
    pts.push([ix + Math.cos(a) * r, y0 + r + Math.sin(a) * r]);
  }
  pts.push([cxm, y0]);
  return makePath(pts);
}
function rrPath(ctx, x, y, w, h, r) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ---------- Layout (unit = minSide, origin = pusat komposisi) ---------- */
const OX = 0.055;
const SUN_X = -0.60, SUN_Y = -0.12, SUN_Y0 = -0.02;
const NAVY = '#1D3557';

const PANEL = { x0: -0.28, y0: -0.17, x1: 0.28, y1: 0.19, r: 0.022 };
const PANEL_R = roundRectHalf(PANEL.x0, PANEL.y0, PANEL.x1, PANEL.y1, PANEL.r, 1, 10);
const PANEL_L = roundRectHalf(PANEL.x0, PANEL.y0, PANEL.x1, PANEL.y1, PANEL.r, -1, 10);
const CELLS = (function () {
  const pad = 0.022, gap = 0.014, cols = 4, rows = 3;
  const cw = (PANEL.x1 - PANEL.x0 - pad * 2 - gap * (cols - 1)) / cols;
  const ch = (PANEL.y1 - PANEL.y0 - pad * 2 - gap * (rows - 1)) / rows;
  const out = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      out.push({ x: PANEL.x0 + pad + c * (cw + gap), y: PANEL.y0 + pad + r * (ch + gap), w: cw, h: ch, s: c + r });
    }
  }
  return out;
})();
const POST = makePath([[0, 0.19], [0, 0.30]]);

const BAT = { x0: 0.50, y0: -0.15, x1: 0.66, y1: 0.15, r: 0.024 };
const BAT_R = roundRectHalf(BAT.x0, BAT.y0, BAT.x1, BAT.y1, BAT.r, 1, 10);
const BAT_L = roundRectHalf(BAT.x0, BAT.y0, BAT.x1, BAT.y1, BAT.r, -1, 10);
const BAT_IN = { x0: 0.518, y0: -0.132, x1: 0.642, y1: 0.132, gap: 0.012 };
const BAR_H = (BAT_IN.y1 - BAT_IN.y0 - BAT_IN.gap * 3) / 4;

const CABLE = makePath(cubicPts([0.305, 0.10], [0.40, 0.10], [0.385, 0.02], [0.482, 0.02], 60));

const BEAM_TARGETS = [[-0.315, -0.135], [-0.315, -0.025], [-0.315, 0.085]];

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 25;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  /* pengaman presisi floating-point di batas scene */
  const cs = Math.max(0, Math.min(sceneCount - 1, currentScene));
  const p = Math.abs(sceneProgress - (loopT / sceneDuration - cs)) < 0.5 ? clamp01(sceneProgress) : clamp01(loopT / sceneDuration - cs);

  const W = width, H = height;
  const minSide = Math.min(W, H);
  const U = minSide;
  const cx = W * 0.5, cy = H * 0.5;
  const TAU = Math.PI * 2;
  const cycle = loopT / duration;

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);

  /* ---------- BACKGROUND (statis) ---------- */
  const bg = ctx.createLinearGradient(0, 0, W * 0.35, H);
  bg.addColorStop(0, '#FFF3E4');
  bg.addColorStop(0.55, '#FBE9E5');
  bg.addColorStop(1, '#E2F0FA');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  let rg = ctx.createRadialGradient(W * 0.06, H * 0.04, 0, W * 0.06, H * 0.04, U * 0.8);
  rg.addColorStop(0, 'rgba(255,214,160,0.45)');
  rg.addColorStop(1, 'rgba(255,214,160,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);

  rg = ctx.createRadialGradient(W * 0.95, H * 0.95, 0, W * 0.95, H * 0.95, U * 0.85);
  rg.addColorStop(0, 'rgba(164,212,244,0.45)');
  rg.addColorStop(1, 'rgba(164,212,244,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);

  /* ---------- STATE ---------- */
  const sunK = phase(cs, p, 0.00, 0.32, 0.84, 1.00);
  const frameK = phase(cs, p, 0.10, 0.42, 0.86, 0.98);
  const backK = phase(cs, p, 0.30, 0.45, 0.82, 0.92);
  const postK = phase(cs, p, 0.30, 0.40, 0.84, 0.92);
  const baseK = phase(cs, p, 0.36, 0.48, 0.78, 0.86);
  const batK = phase(cs, p, 0.58, 0.80, 0.80, 0.94);
  const capK = phase(cs, p, 0.74, 0.82, 0.76, 0.84);
  const slotK = phase(cs, p, 0.70, 0.82, 0.72, 0.82);
  const textK = phase(cs, p, 0.72, 0.84, 0.70, 0.80);
  const cableK = phase(cs, p, 0.76, 0.94, 0.72, 0.84);
  const jackPK = phase(cs, p, 0.72, 0.78, 0.82, 0.88);
  const jackBK = phase(cs, p, 0.90, 0.95, 0.72, 0.77);
  const barsA = cs === 2 ? 1 - easeInOutCubic(seg(p, 0.70, 0.80)) : 1;

  const level = 4 * easeInOutSine(seg(loopT, 10.0, 20.4));
  const flowA = smoothstep(seg(loopT, 9.0, 9.8)) * (1 - smoothstep(seg(loopT, 22.0, 22.6)));
  const beamA = smoothstep(seg(loopT, 8.6, 9.4)) * (1 - smoothstep(seg(loopT, 22.0, 22.6)));

  let shimmer = -1;
  const sweeps = cs === 1 ? [[0.10, 0.40], [0.56, 0.86]] : (cs === 2 ? [[0.46, 0.66]] : []);
  for (let i = 0; i < sweeps.length; i++) {
    const q = seg(p, sweeps[i][0], sweeps[i][1]);
    if (q > 0 && q < 1) shimmer = easeInOutSine(q);
  }

  ctx.translate(cx + OX * U, cy);
  ctx.scale(U, U);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  /* ---------- BERKAS SINAR (dash bergerak) ---------- */
  if (beamA > 0.001) {
    ctx.setLineDash([0.02, 0.016]);
    ctx.lineDashOffset = -loopT * 0.05;
    ctx.lineWidth = 0.007;
    ctx.strokeStyle = 'rgba(240,150,20,' + (0.9 * beamA).toFixed(4) + ')';
    for (let i = 0; i < BEAM_TARGETS.length; i++) {
      const tx = BEAM_TARGETS[i][0], ty = BEAM_TARGETS[i][1];
      const dx = tx - SUN_X, dy = ty - SUN_Y, dl = Math.hypot(dx, dy);
      ctx.beginPath();
      ctx.moveTo(SUN_X + dx / dl * 0.21, SUN_Y + dy / dl * 0.21);
      ctx.lineTo(tx, ty);
      ctx.stroke();
    }
    ctx.setLineDash([]);
    ctx.lineDashOffset = 0;
  }

  /* ---------- MATAHARI ---------- */
  const sunA = clamp01(sunK * 1.6);
  if (sunA > 0.001) {
    const sy = lerp(SUN_Y0, SUN_Y, sunK), sc = lerp(0.8, 1, sunK);
    ctx.save();
    ctx.globalAlpha = sunA;
    ctx.translate(SUN_X, sy);
    ctx.scale(sc, sc);

    const rot = (Math.PI / 3) * cycle;
    ctx.strokeStyle = '#F59E0B';
    ctx.lineWidth = 0.012;
    for (let i = 0; i < 12; i++) {
      let rk;
      if (cs === 0) rk = easeOutCubic(seg(p, 0.14 + i * 0.012, 0.34 + i * 0.012));
      else if (cs === 1) rk = 1;
      else rk = 1 - easeInOutCubic(seg(p, 0.78 + i * 0.006, 0.88 + i * 0.006));
      if (rk <= 0.001) continue;
      const odd = i % 2;
      const rEnd = (odd ? 0.150 : 0.165) * (1 + 0.035 * Math.sin(TAU * 2 * cycle + odd * Math.PI));
      const r0 = 0.128, r1 = r0 + (rEnd - r0) * rk;
      const a = rot + i * TAU / 12;
      ctx.beginPath();
      ctx.moveTo(Math.cos(a) * r0, Math.sin(a) * r0);
      ctx.lineTo(Math.cos(a) * r1, Math.sin(a) * r1);
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(0, 0, 0.108, 0, TAU);
    ctx.lineWidth = 0.006;
    ctx.strokeStyle = 'rgba(245,158,11,0.6)';
    ctx.stroke();

    const sg = ctx.createLinearGradient(-0.06, -0.08, 0.06, 0.08);
    sg.addColorStop(0, '#FFE08A');
    sg.addColorStop(1, '#FFB547');
    ctx.beginPath();
    ctx.arc(0, 0, 0.085, 0, TAU);
    ctx.fillStyle = sg;
    ctx.fill();
    ctx.restore();
  }

  /* ---------- PANEL SURYA ---------- */
  if (backK > 0.001) {
    rrPath(ctx, PANEL.x0, PANEL.y0, PANEL.x1 - PANEL.x0, PANEL.y1 - PANEL.y0, PANEL.r);
    ctx.fillStyle = 'rgba(238,244,255,' + backK.toFixed(4) + ')';
    ctx.fill();
  }

  for (let i = 0; i < CELLS.length; i++) {
    const c = CELLS[i];
    let k;
    if (cs === 0) k = easeOutCubic(seg(p, 0.40 + c.s * 0.05, 0.58 + c.s * 0.05));
    else if (cs === 1) k = 1;
    else k = 1 - easeInOutCubic(seg(p, 0.70 + (5 - c.s) * 0.024, 0.80 + (5 - c.s) * 0.024));
    if (k <= 0.001) continue;
    const sc = lerp(0.6, 1, k);
    const mx = c.x + c.w / 2, my = c.y + c.h / 2;
    const w = c.w * sc, h = c.h * sc;
    ctx.save();
    ctx.globalAlpha = k;
    const cg = ctx.createLinearGradient(0, my - h / 2, 0, my + h / 2);
    cg.addColorStop(0, '#5B9DF9');
    cg.addColorStop(1, '#2F6BE0');
    rrPath(ctx, mx - w / 2, my - h / 2, w, h, 0.008 * sc);
    ctx.fillStyle = cg;
    ctx.fill();
    ctx.lineWidth = 0.0025;
    ctx.strokeStyle = 'rgba(255,255,255,0.38)';
    ctx.beginPath();
    ctx.moveTo(mx - w * 0.36, my);
    ctx.lineTo(mx + w * 0.36, my);
    ctx.moveTo(mx, my - h * 0.30);
    ctx.lineTo(mx, my + h * 0.30);
    ctx.stroke();
    ctx.restore();
  }

  /* pantulan cahaya (sweep diagonal, tepi tajam) */
  if (shimmer >= 0) {
    const xs = lerp(-0.46, 0.46, shimmer);
    ctx.save();
    ctx.beginPath();
    for (let i = 0; i < CELLS.length; i++) {
      const c = CELLS[i];
      ctx.rect(c.x, c.y, c.w, c.h);
    }
    ctx.clip();
    ctx.fillStyle = 'rgba(255,255,255,0.30)';
    ctx.beginPath();
    ctx.moveTo(xs - 0.035 + 0.06, PANEL.y0);
    ctx.lineTo(xs + 0.035 + 0.06, PANEL.y0);
    ctx.lineTo(xs + 0.035 - 0.06, PANEL.y1);
    ctx.lineTo(xs - 0.035 - 0.06, PANEL.y1);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(255,255,255,0.20)';
    ctx.beginPath();
    ctx.moveTo(xs + 0.055 + 0.06, PANEL.y0);
    ctx.lineTo(xs + 0.070 + 0.06, PANEL.y0);
    ctx.lineTo(xs + 0.070 - 0.06, PANEL.y1);
    ctx.lineTo(xs + 0.055 - 0.06, PANEL.y1);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  /* frame panel + tiang */
  ctx.strokeStyle = NAVY;
  ctx.lineWidth = 0.010;
  strokeRange(ctx, PANEL_R, 0, frameK * PANEL_R.len);
  strokeRange(ctx, PANEL_L, 0, frameK * PANEL_L.len);
  ctx.lineWidth = 0.012;
  strokeRange(ctx, POST, 0, postK * POST.len);
  if (baseK > 0.001) {
    ctx.beginPath();
    ctx.moveTo(-0.10 * baseK, 0.30);
    ctx.lineTo(0.10 * baseK, 0.30);
    ctx.stroke();
  }

  /* ---------- KABEL ENERGI ---------- */
  ctx.fillStyle = NAVY;
  if (jackPK > 0.001) {
    ctx.save();
    ctx.globalAlpha = jackPK;
    rrPath(ctx, 0.284, 0.086, 0.022, 0.028, 0.006);
    ctx.fill();
    ctx.restore();
  }
  if (jackBK > 0.001) {
    ctx.save();
    ctx.globalAlpha = jackBK;
    rrPath(ctx, 0.481, 0.006, 0.022, 0.028, 0.006);
    ctx.fill();
    ctx.restore();
  }
  ctx.strokeStyle = NAVY;
  ctx.lineWidth = 0.010;
  strokeRange(ctx, CABLE, 0, cableK * CABLE.len);

  if (flowA > 0.001 && cableK > 0.999) {
    ctx.fillStyle = '#F5A524';
    for (let k = 0; k < 3; k++) {
      const u = (loopT * 0.25 + k / 3) % 1;
      const pt = pointAt(CABLE, u * CABLE.len);
      ctx.globalAlpha = flowA * Math.sin(Math.PI * u);
      ctx.beginPath();
      ctx.arc(pt[0], pt[1], 0.0115, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }

  /* ---------- BATERAI ---------- */
  if (slotK > 0.001) {
    ctx.fillStyle = 'rgba(29,53,87,' + (0.10 * slotK).toFixed(4) + ')';
    for (let k = 0; k < 4; k++) {
      const yb = BAT_IN.y1 - k * (BAR_H + BAT_IN.gap);
      rrPath(ctx, BAT_IN.x0, yb - BAR_H, BAT_IN.x1 - BAT_IN.x0, BAR_H, 0.008);
      ctx.fill();
    }
  }
  if (barsA > 0.001 && level > 0.0005) {
    const bgd = ctx.createLinearGradient(0, BAT_IN.y0, 0, BAT_IN.y1);
    bgd.addColorStop(0, '#3DD598');
    bgd.addColorStop(1, '#1FA776');
    ctx.fillStyle = bgd;
    ctx.globalAlpha = barsA;
    for (let k = 0; k < 4; k++) {
      const f = clamp01(level - k);
      if (f <= 0.0005) continue;
      const yb = BAT_IN.y1 - k * (BAR_H + BAT_IN.gap);
      const h = BAR_H * f;
      rrPath(ctx, BAT_IN.x0, yb - h, BAT_IN.x1 - BAT_IN.x0, h, 0.008);
      ctx.fill();
    }
    ctx.globalAlpha = 1;
  }
  ctx.strokeStyle = NAVY;
  ctx.lineWidth = 0.012;
  strokeRange(ctx, BAT_R, 0, batK * BAT_R.len);
  strokeRange(ctx, BAT_L, 0, batK * BAT_L.len);
  if (capK > 0.001) {
    ctx.save();
    ctx.globalAlpha = capK;
    ctx.fillStyle = NAVY;
    rrPath(ctx, 0.55, -0.178, 0.06, 0.024, 0.006);
    ctx.fill();
    ctx.restore();
  }

  /* ---------- LABEL PERSENTASE (piksel, tajam) ---------- */
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  if (textK > 0.001) {
    const pct = Math.round(level * 25);
    ctx.globalAlpha = textK;
    ctx.fillStyle = NAVY;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '600 ' + Math.round(U * 0.042) + 'px "Segoe UI", Inter, Arial, sans-serif';
    ctx.fillText(pct + '%', cx + (OX + 0.58) * U, cy + 0.245 * U);
    ctx.globalAlpha = 1;
  }

  ctx.restore();
}

/*
 * Sustainability 02 — Water-Saving Precision
 * 25 seconds / 3 scenes / 3840 x 2160 / 60 fps.
 * Self-contained, deterministic Canvas 2D. Time is supplied in SECONDS.
 * Export target: 100,000,000 bits/second, set in the video encoder.
 * A Canvas drawing function does not encode or enforce a video bitrate.
 * Revision: fixed-size droplets, impact-timed ripples, rigid handle attachment.
 */

const WaterSavingPrecision = (() => {
  const TAU = Math.PI * 2;
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const fract = v => v - Math.floor(v);
  const mix = (a, b, p) => a + (b - a) * p;
  const ease = p => {
    p = clamp(p);
    return p * p * p * (p * (p * 6 - 15) + 10);
  };
  const ramp = (a, b, v) => ease((v - a) / (b - a));
  const geometry = Object.freeze({
    waterX: 189, outletY: -48, dropStartY: -55, dropRadius: 5.6,
    initialVelocity: 30, gravity: 520, cadence: 1.25 / 3,
    maxFlight: 1.25, rippleDuration: 0.80,
    centerX: 21.5, centerY: 54
  });
  const normalize = time => Number.isFinite(time) ? ((time % 25) + 25) % 25 : 0;

  function water(time) {
    const phase = TAU * normalize(time) / 25;
    const level = 0.40 + 0.17 * (1 - Math.cos(phase)) / 2;
    const surfaceY = 333 - level * 190;
    const wave = phase * 5;
    return { phase, surfaceY, wave,
      impactY: surfaceY + Math.sin(Math.PI + wave) * 1.2 };
  }

  function state(time) {
    const t = normalize(time), sceneDuration = 25 / 3;
    const scene = Math.min(2, Math.floor(t / sceneDuration));
    const progress = (t - scene * sceneDuration) / sceneDuration;
    const handoff = ramp(0.85, 1, progress);
    const weights = [0, 0, 0];
    weights[scene] = 1 - handoff;
    weights[(scene + 1) % 3] = handoff;
    let valve = 0.82;
    // Equal six-second travel times in both directions, with C2 easing.
    if (scene === 1) valve = mix(0.82, 0.28, ramp(0.08, 0.80, progress));
    if (scene === 2) valve = mix(0.28, 0.82, ramp(0.28, 1, progress));
    const streamOpacity = ramp(0.36, 0.60, valve);
    return { t, scene, progress, weights, valve,
      saving: 1 - ramp(0.30, 0.81, valve),
      streamOpacity, dropOpacity: 1 - streamOpacity,
      ...water(t) };
  }

  function fallY(age) {
    return geometry.dropStartY + geometry.initialVelocity * age + geometry.gravity * age * age / 2;
  }

  function impactAge(birth) {
    // Solve against the moving surface. The lower Bezier lobe reaches 1.035 r.
    let lo = 0, hi = geometry.maxFlight;
    for (let i = 0; i < 18; i++) {
      const age = (lo + hi) / 2;
      if (fallY(age) + geometry.dropRadius * 1.035 < water(birth + age).impactY) lo = age;
      else hi = age;
    }
    return (lo + hi) / 2;
  }

  function events(time) {
    // Keep live cohorts across phase changes and across the loop boundary.
    // Release strength is retained by each cohort instead of being reassigned
    // whenever the valve changes. A returning jet can absorb live droplets.
