    // All background coordinates and colors are independent of time.
    const g = ctx.createLinearGradient(0, 0, width, height);
    g.addColorStop(0, '#172B40');
    g.addColorStop(0.54, '#1D414B');
    g.addColorStop(1, '#41615D');
    ctx.fillStyle = g; ctx.fillRect(0, 0, width, height);

    ctx.beginPath();
    ctx.moveTo(0, height * 0.69);
    ctx.bezierCurveTo(width * 0.11, height * 0.60, width * 0.18, height * 0.84, width * 0.34, height);
    ctx.lineTo(0, height); ctx.closePath();
    ctx.fillStyle = 'rgba(168,196,184,0.035)'; ctx.fill();

    ctx.beginPath();
    ctx.moveTo(width * 0.76, 0);
    ctx.bezierCurveTo(width * 0.85, height * 0.14, width * 0.91, height * 0.21, width, height * 0.23);
    ctx.lineTo(width, 0); ctx.closePath();
    ctx.fillStyle = 'rgba(207,222,211,0.025)'; ctx.fill();
  }

  function visibility(p, opacity) {
    // Packets reset only while fully transparent, with zero fade slope.
    return ramp(0, 0.12, p) * (1 - ramp(0.88, 1, p)) * clamp(opacity);
  }

  function packet(ctx, x0, y0, x1, y1, p, opacity, ink, length = 20, lw = 5) {
    const distance = Math.hypot(x1 - x0, y1 - y0);
    if (distance <= 0) return;
    const half = Math.min(length, distance) / (2 * distance);
    const center = mix(half, 1 - half, clamp(p));
    const a = center - half, b = center + half;
    const alpha = visibility(p, opacity);
    if (alpha <= 0) return;
    ctx.save(); ctx.globalAlpha *= alpha;
    line(ctx, [[mix(x0, x1, a), mix(y0, y1, a)], [mix(x0, x1, b), mix(y0, y1, b)]], ink, lw);
    ctx.restore();
  }

  function route(vertices, radius = 8) {
    // Precompute smooth corners once; packet travel is measured by path length.
    const points = [vertices[0].slice()];
    for (let i = 1; i < vertices.length - 1; i++) {
      const a = vertices[i - 1], b = vertices[i], c = vertices[i + 1];
      const before = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, before / 2, after / 2);
      const start = [b[0] + (a[0] - b[0]) * r / before, b[1] + (a[1] - b[1]) * r / before];
      const end = [b[0] + (c[0] - b[0]) * r / after, b[1] + (c[1] - b[1]) * r / after];
      points.push(start);
      for (let j = 1; j <= 16; j++) {
        const p = j / 16, q = 1 - p;
        points.push([q * q * start[0] + 2 * q * p * b[0] + p * p * end[0],
          q * q * start[1] + 2 * q * p * b[1] + p * p * end[1]]);
      }
    }
    points.push(vertices[vertices.length - 1].slice());
    const distances = [0];
    for (let i = 1; i < points.length; i++) {
      distances.push(distances[i - 1] + Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]));
    }
    return { points, distances, length: distances[distances.length - 1] };
  }

  function routeRange(ctx, path, from, to, ink, lw) {
    from = clamp(from, 0, path.length); to = clamp(to, 0, path.length);
    if (to <= from) return;
    ctx.beginPath();
    let started = false;
    for (let i = 1; i < path.points.length; i++) {
      const d0 = path.distances[i - 1], d1 = path.distances[i];
      if (d1 <= from || d0 >= to || d1 <= d0) continue;
      const a = path.points[i - 1], b = path.points[i];
      const p = clamp((from - d0) / (d1 - d0));
      const q = clamp((to - d0) / (d1 - d0));
      if (!started) { ctx.moveTo(mix(a[0], b[0], p), mix(a[1], b[1], p)); started = true; }
      ctx.lineTo(mix(a[0], b[0], q), mix(a[1], b[1], q));
    }
    ctx.strokeStyle = ink; ctx.lineWidth = lw; ctx.stroke();
  }

  function routedPacket(ctx, path, p, opacity, ink, length = 24, lw = 5, limit = path.length) {
    const size = Math.min(length, path.length);
    const start = (path.length - size) * clamp(p);
    const alpha = visibility(p, opacity);
    if (alpha <= 0 || start >= limit) return;
    ctx.save(); ctx.globalAlpha *= alpha;
    routeRange(ctx, path, start, Math.min(start + size, limit), ink, lw);
    ctx.restore();
  }

  // Mirrored branches merge under the fixed coupler; the stem is painted once.
  const leftRoute = route([[-334, 194], [-20, 194], [-20, 213], [0, 213], [0, 306]]);
  const rightRoute = route([[334, 194], [20, 194], [20, 213], [0, 213], [0, 306]]);
  const branchEnd = leftRoute.length - (306 - 221);

  return { TAU, clamp, fract, mix, ease, ramp, travel, color, rounded, box, line, circle, bolt, screw,
    background, packet, routedPacket, routeRange, leftRoute, rightRoute, branchEnd, layout, state };
})();

function draw(ctx, time, width, height) {
  const M = SolarEnergyHub;
  const { t: loopT, weights, level } = M.state(time);
  const { panel, well, cells, dock, battery } = M.layout;
  const minSide = Math.min(width, height);

  // Scene 1: collection. Scene 2: storage. Scene 3: distribution.
  // Only internal emphasis crossfades; the solid icon never fades or shifts.
  const collection = weights[0], storage = weights[1], distribution = weights[2];
  const ink = '#142F40';

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.setLineDash([]);
  ctx.lineDashOffset = 0;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  M.background(ctx, width, height);

  ctx.translate(width / 2, height / 2 + minSide * 0.014);
  ctx.scale(minSide / 1080, minSide / 1080);

  // Sun: solid paint and finite line work, without halos or blurred effects.
  const sunX = 0, sunY = -344;
  for (let i = 0; i < 12; i++) {
    const a = i * M.TAU / 12;
    const inner = 48;
    const outer = 62;
    M.line(ctx, [[sunX + Math.cos(a) * inner, sunY + Math.sin(a) * inner], [sunX + Math.cos(a) * outer, sunY + Math.sin(a) * outer]], '#D4AC68', 4);
  }
  const sunFill = ctx.createLinearGradient(-24, -379, 25, -310);
  sunFill.addColorStop(0, '#F1D598'); sunFill.addColorStop(1, '#D6AC68');
  M.circle(ctx, sunX, sunY, 34, sunFill, ink, 4.5);
  M.line(ctx, [[-11, -354], [7, -354]], '#F6E4BC', 3.5);

  // A reserved corridor carries solar input to the upper panel edge.
  const rayXs = [-112, 0, 112];
  for (let i = 0; i < 3; i++) {
    const x = rayXs[i];
    const startY = -268;
    const endY = -244;
    M.line(ctx, [[x, startY], [x, endY]], '#779091', 2.5);
    const p = M.fract(loopT / 2.5 - (i === 1 ? 0 : 0.12));
    M.packet(ctx, x, startY, x, endY, p, 0.08 + collection * 0.92, '#E9C784', 8, 4);
  }

  // The support and energy dock are drawn behind their attachment seams.
  M.box(ctx, -35, 213, 70, 86, 10, '#A8C2BF', ink, 5);
  M.box(ctx, -10, 224, 20, 65, 7, '#284C57', ink, 3);
  M.line(ctx, [[0, 226], [0, 289]], '#5F8F98', 4);

  // Two output sockets belong to the lower dock and remain visible in all scenes.
  M.line(ctx, [[-245, 341], [-354, 341]], ink, 15);
  M.line(ctx, [[-245, 341], [-354, 341]], '#88AAA8', 7);
  M.line(ctx, [[245, 341], [354, 341]], ink, 15);
  M.line(ctx, [[245, 341], [354, 341]], '#88AAA8', 7);
  for (let i = 0; i < 2; i++) {
    const q = M.fract(loopT / 2.5 - 0.20 + i * 0.5);
    M.packet(ctx, -250, 341, -350, 341, q, 0.06 + 0.94 * distribution, '#D3DFB0', 15, 5);
    M.packet(ctx, 250, 341, 350, 341, q, 0.06 + 0.94 * distribution, '#D3DFB0', 15, 5);
  }
  M.box(ctx, -376, 325, 26, 32, 6, '#ADC5BE', ink, 4);
  M.box(ctx, 350, 325, 26, 32, 6, '#ADC5BE', ink, 4);
  M.line(ctx, [[-363, 334], [-363, 348]], ink, 3);
  M.line(ctx, [[363, 334], [363, 348]], ink, 3);

  // One front-facing panel silhouette: no perspective or nonuniform scaling.
  const frameFill = ctx.createLinearGradient(-400, -222, 400, 224);
  frameFill.addColorStop(0, '#C8DAD5'); frameFill.addColorStop(1, '#95B5B3');
  M.box(ctx, panel.x, panel.y, panel.w, panel.h, panel.r, frameFill, ink, 5.5);
  M.box(ctx, well.x, well.y, well.w, well.h, well.r, '#163D54', ink, 3.5);

  // Header details share one baseline and a fixed inner margin.
  M.box(ctx, -350, -202, 61, 12, 6, '#769B9D', null);
  M.box(ctx, -277, -202, 34, 12, 6, '#93B6B2', null);
  for (let i = 0; i < 3; i++) {
    const v = weights[i];
    M.box(ctx, 268 + i * 25, -204, 16, 16, 5, M.color('#729698', '#D9DBB2', v), ink, 2.1);
  }

  // A single fixed gradient serves all cells; moving accents are clipped per cell.
  const cellFill = ctx.createLinearGradient(-360, -150, 360, 158);
  cellFill.addColorStop(0, '#316781'); cellFill.addColorStop(1, '#244F6A');
  const sweepPhase = M.fract(loopT / 6.25);
  const sweepX = -620 + 1240 * M.travel(sweepPhase);
  for (let row = 0; row < cells.rows; row++) {
    for (let col = 0; col < cells.cols; col++) {
      const x = cells.x + col * (cells.w + cells.gap);
      const y = cells.y + row * (cells.h + cells.gap);
      M.rounded(ctx, x, y, cells.w, cells.h, 7);
      ctx.fillStyle = cellFill; ctx.fill();
      ctx.save(); ctx.clip();

      // Cell bus fingers are fine, continuous, and evenly inset.
      for (let k = 1; k <= 3; k++) {
        M.line(ctx, [[x + 9, y + k * 17], [x + 101, y + k * 17]], '#648B9C', 1.35);
      }
      M.line(ctx, [[x + 36, y + 7], [x + 36, y + 61]], '#8CA8AC', 1.8);
      M.line(ctx, [[x + 74, y + 7], [x + 74, y + 61]], '#8CA8AC', 1.8);

      ctx.globalAlpha = 0.18 * collection;
      ctx.beginPath();
      ctx.moveTo(sweepX - 42, -180);
      ctx.lineTo(sweepX + 42, -180);
      ctx.lineTo(sweepX + 154, 180);
      ctx.lineTo(sweepX + 70, 180);
      ctx.closePath(); ctx.fillStyle = '#C9D6B9'; ctx.fill();
      ctx.globalAlpha = 1;

      const pair = Math.min(col, cells.cols - 1 - col);
      const p = M.fract(loopT / 2.5 - row * 0.06 - pair * 0.08);
      const leftToRight = col < cells.cols / 2;
      M.packet(ctx, x + (leftToRight ? 12 : 98), y + 51,
        x + (leftToRight ? 98 : 12), y + 51, p,
        0.06 + 0.30 * collection + 0.44 * storage, '#A3C8CA', 13, 2.4);
      ctx.restore();
      M.rounded(ctx, x, y, cells.w, cells.h, 7);
      ctx.strokeStyle = ink; ctx.lineWidth = 2.7; ctx.stroke();
    }
  }

  // Collection bus has a separate corridor below the cells.
  M.routeRange(ctx, M.leftRoute, 0, M.leftRoute.length, '#577F87', 4);
  M.routeRange(ctx, M.rightRoute, 0, M.branchEnd, '#577F87', 4);
  for (let i = 0; i < 3; i++) {
    const p = M.fract(loopT / 5 - 0.17 + i / 3);
    const opacity = 0.08 + storage * 0.92;
    M.routedPacket(ctx, M.leftRoute, p, opacity, '#B6D7C9', 24, 5);
    M.routedPacket(ctx, M.rightRoute, p, opacity, '#B6D7C9', 24, 5, M.branchEnd);
  }
  M.box(ctx, -17, 204, 34, 22, 5, '#608D95', ink, 3);
  for (const x of [-383, 383]) {
    for (const y of [-202, 204]) M.screw(ctx, x, y);
  }

  // Energy dock: six independent segments, fixed padding, no changing text.
  const dockFill = ctx.createLinearGradient(-245, 289, 245, 393);
  dockFill.addColorStop(0, '#C7D8CA'); dockFill.addColorStop(1, '#A6C1B9');
  M.box(ctx, dock.x, dock.y, dock.w, dock.h, dock.r, dockFill, ink, 5);
  M.line(ctx, [[-222, 309], [221, 309]], '#83A69F', 2);
  M.bolt(ctx, -208, 346, 0.92, '#2C5F64');
  M.box(ctx, battery.x, battery.y, battery.w, battery.h, 10, '#244854', ink, 3);

  const segmentWidth = (battery.w - 2 * battery.padding - (battery.count - 1) * battery.gap) / battery.count;
  const segmentY = battery.y + 8;
  for (let i = 0; i < battery.count; i++) {
    const x = battery.x + battery.padding + i * (segmentWidth + battery.gap);
    M.box(ctx, x, segmentY, segmentWidth, 32, 4, '#3E6570', null);
    const amount = M.clamp(level * battery.count - i);
    if (amount > 0) {
      ctx.save(); M.rounded(ctx, x, segmentY, segmentWidth, 32, 4); ctx.clip();
      ctx.fillStyle = '#B8D3B3';
      ctx.fillRect(x, segmentY, segmentWidth * amount, 32);
      ctx.restore();
    }
  }
  M.box(ctx, 117, 335, 6, 18, 2, '#244854', null);

  // Output gauge keeps its needle and ticks within the face at every angle.
  M.circle(ctx, 177, 344, 30, '#E2E6D2', ink, 3.5);
  for (let i = 0; i <= 6; i++) {
    const a = Math.PI * (1.12 + i * 0.125);
    M.line(ctx, [[177 + 20 * Math.cos(a), 344 + 20 * Math.sin(a)], [177 + 24 * Math.cos(a), 344 + 24 * Math.sin(a)]], '#74948A', 2);
  }
  const needle = Math.PI * M.mix(1.12, 1.87, 0.28 + distribution * 0.60);
  M.line(ctx, [[177, 344], [177 + Math.cos(needle) * 18, 344 + Math.sin(needle) * 18]], '#345D62', 3);
  M.circle(ctx, 177, 344, 3.5, '#345D62', null);
  M.screw(ctx, -224, 375); M.screw(ctx, 224, 375);

  ctx.restore();
}

// Optional render-host hints. The host must enforce the encoder configuration.
draw.duration = 25;
draw.sceneCount = 3;
draw.fps = 60;
draw.width = 3840;
draw.height = 2160;
draw.bitrate = 100000000;
